import { Metadata } from 'next'
import { client, urlFor } from '@/lib/sanity'
import { PortableText } from '@portabletext/react'
import { RichTextComponents } from '@/components/RichTextComponents'
import Image from 'next/image'
import Link from 'next/link'
import { notFound } from 'next/navigation'
import { ArrowLeft, Calendar, Clock, Share2 } from 'lucide-react'
import { Button } from '@/components/ui/button'

type Props = {
  params: Promise<{ slug: string }>
}

export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const { slug } = await params
  const query = `*[_type == "post" && slug.current == $slug][0] { title, description }`
  const post = await client.fetch(query, { slug })

  if (!post) {
    return {
      title: 'Not Found',
    }
  }

  return {
    title: `${post.title} | Chân Kinh Online`,
    description: post.description,
  }
}

// Revalidate every 60 seconds
export const revalidate = 60

export default async function PostPage({ params }: Props) {
  const { slug } = await params
  const query = `
    *[_type == "post" && slug.current == $slug][0] {
      ...,
      "elementName": element,
      content,
    }
  `
  const post = await client.fetch(query, { slug })

  if (!post) {
    notFound()
  }

  return (
    <article className="min-h-screen pb-20 pt-10 px-4 md:px-0 bg-background selection:bg-[#c5a059]/30">
      {/* Navigation Bar */}
      <div className="max-w-3xl mx-auto mb-12 flex items-center justify-between animate-fadeIn">
        <Link href="/kinh-cac">
          <Button variant="ghost" className="group text-muted-foreground hover:text-[#c5a059] flex items-center gap-2 pl-0 hover:bg-transparent tracking-wide transition-colors">
            <ArrowLeft className="w-5 h-5 group-hover:-translate-x-1 transition-transform" />
            <span className="font-sans font-medium">Back to Library</span>
          </Button>
        </Link>

        <div className="flex gap-2">
          <Button variant="ghost" size="icon" className="text-muted-foreground hover:text-[#c5a059] hover:bg-transparent transition-colors">
            <Share2 className="w-5 h-5" />
          </Button>
        </div>
      </div>

      <div className="max-w-3xl mx-auto space-y-8 animate-slideUp">
        {/* Header Section */}
        <header className="space-y-6 text-center md:text-left">
          {/* Element Badge */}
          <div className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full border border-[#c5a059]/30 bg-[#c5a059]/5 text-[#c5a059] text-xs font-semibold uppercase tracking-widest">
            <span className="w-1.5 h-1.5 rounded-full bg-[#c5a059]" />
            {post.elementName || 'Kinh Cac'}
          </div>

          {/* Title */}
          <h1 className="text-4xl md:text-5xl lg:text-6xl font-serif font-bold text-[#c5a059] leading-tight tracking-tight">
            {post.title}
          </h1>

          {/* Description */}
          <p className="text-xl md:text-2xl text-muted-foreground font-sans font-light leading-relaxed max-w-2xl">
            {post.description}
          </p>

          {/* Meta Info */}
          <div className="flex flex-wrap items-center justify-center md:justify-start gap-6 text-sm text-muted-foreground font-sans border-t border-border/40 pt-6 mt-6">
            <div className="flex items-center gap-2">
              <Calendar className="w-4 h-4 text-[#c5a059]" />
              <span className="tracking-wide">{new Date(post.publishedAt).toLocaleDateString('vi-VN', { year: 'numeric', month: 'long', day: 'numeric' })}</span>
            </div>
            {post.readTime && (
              <div className="flex items-center gap-2">
                <Clock className="w-4 h-4 text-[#c5a059]" />
                <span className="tracking-wide">{post.readTime} min read</span>
              </div>
            )}
          </div>
        </header>

        {/* Main Image */}
        {post.mainImage && (
          <div className="relative w-full aspect-video rounded-xl overflow-hidden shadow-2xl border border-border/20 my-12 group">
            <Image
              src={urlFor(post.mainImage).url()}
              alt={post.title}
              fill
              className="object-cover transition-transform duration-1000 group-hover:scale-105"
              priority
            />
            <div className="absolute inset-0 bg-gradient-to-t from-background/90 via-transparent to-transparent opacity-60 pointer-events-none" />
          </div>
        )}

        {/* Content */}
        <div className="prose prose-lg dark:prose-invert max-w-none pb-12 border-b border-border/40">
          <PortableText value={post.content} components={RichTextComponents} />
        </div>

        {/* Footer / Navigation */}
        <div className="pt-8 flex justify-center">
          <Link href="/kinh-cac">
            <Button variant="outline" className="border-[#c5a059] text-[#c5a059] hover:bg-[#c5a059] hover:text-white px-10 py-6 rounded-none uppercase tracking-widest font-serif transition-all duration-500">
              Return to Library
            </Button>
          </Link>
        </div>
      </div>
    </article>
  )
}
